describe('401 Error Handling - Redirect to Login', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should redirect to login when API returns 401 Unauthorized', () => {
    // Intercept the protected API endpoint
    cy.intercept('GET', '/api/user/profile', {
      statusCode: 401,
      body: { error: 'Unauthorized' }
    }).as('unauthorizedRequest');

    // Attempt to access a protected resource
    cy.get('[data-testid="profile-button"]').click();

    // Wait for the API call
    cy.wait('@unauthorizedRequest');

    // Verify redirect to login page
    cy.url().should('include', '/login');

    // Verify login form is visible
    cy.get('[data-testid="login-form"]').should('be.visible');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('contain', 'Unauthorized');
  });

  it('should handle multiple 401 errors and maintain redirect to login', () => {
    // Intercept the first API call with 401
    cy.intercept('GET', '/api/user/settings', {
      statusCode: 401,
      body: { error: 'Unauthorized' }
    }).as('firstUnauthorized');

    // Intercept the second API call with 401
    cy.intercept('GET', '/api/user/preferences', {
      statusCode: 401,
      body: { error: 'Unauthorized' }
    }).as('secondUnauthorized');

    // First API call triggers redirect
    cy.get('[data-testid="settings-button"]').click();
    cy.wait('@firstUnauthorized');

    // Verify redirect to login
    cy.url().should('include', '/login');

    // Navigate back to dashboard (simulating user returning)
    cy.visit('/dashboard');

    // Second API call should also trigger redirect
    cy.get('[data-testid="preferences-button"]').click();
    cy.wait('@secondUnauthorized');

    // Verify still on login page
    cy.url().should('include', '/login');
    cy.get('[data-testid="login-form"]').should('be.visible');
  });
});
